BEGIN;
SET LOCAL transaction_read_only=off;
SET LOCAL lock_timeout='2s';
SET LOCAL statement_timeout='30s';
CREATE FUNCTION collaboration.s0_deny_mutation() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$ BEGIN RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='S0_DESTRUCTIVE_TRANSITION_FENCED'; END $$;
REVOKE ALL ON FUNCTION collaboration.s0_deny_mutation() FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER aa_s0_delete BEFORE DELETE ON auth.users FOR EACH ROW EXECUTE FUNCTION collaboration.s0_deny_mutation();
